/*
 * chips/bk7258/wifi/glue/include/wpa_compat/sk_intf.h
 *
 * Management/L2 packet interface between the Wi-Fi glue and wpa_supplicant.
 * Replaces the vendored bk_patch/sk_intf.h rather than forwarding to it,
 * because that header includes fake_socket.h, whose `enum sock_type` and
 * `struct sockaddr` collide with the NuttX socket layer.
 *
 * Only what the compiled glue actually references is declared (verified over
 * rw_task.c / rwnx_rx.c / rwnx_tx.c / rw_msdu.c):
 *
 *   struct ke_sk_params    all four files
 *   ke_mgmt_packet_tx()    rwnx_rx.c, rwnx_tx.c, rw_msdu.c
 *   ke_mgmt_packet_rx()    rw_task.c
 *   ke_l2_packet_rx()      rw_task.c
 *
 * The socket-number helpers (mgmt/data/ioctl_get_socket_num) and the
 * SK_INTF_*_SOCKET_NUM macros are deliberately absent: nothing in the compiled
 * set uses them, and they only make sense with Armino's fake socket layer.
 * EAPOL/WAI (0x888e) demux to the WPA entity is the network bridge's job
 * (plan §11.4.2), not this header's.
 */

#ifndef __BK7258_WIFI_GLUE_WPA_COMPAT_SK_INTF_H
#define __BK7258_WIFI_GLUE_WPA_COMPAT_SK_INTF_H

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Management packet TX/RX parameters. Layout must match the vendored
 * definition: the glue fills it and wpa_supplicant reads it.
 */

struct ke_sk_params
{
  unsigned char *buf;  /* Buffer pointer */
  int            len;  /* Buffer length */
  int            flag; /* VIF index / flag */
  uint32_t       freq; /* Frequency in MHz */
};

int ke_mgmt_peek_rxed_next_payload_size(int flag);
int ke_mgmt_packet_rx(struct ke_sk_params *params);
int ke_mgmt_packet_tx(const struct ke_sk_params *params);
int ke_l2_packet_tx(const struct ke_sk_params *params);
int ke_l2_packet_rx(struct ke_sk_params *params);
int ke_data_peek_txed_next_payload_size(int flag);
int ke_data_peek_rxed_next_payload_size(int flag);

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_WPA_COMPAT_SK_INTF_H */

/*
 * chips/bk7258/wifi/glue/include/wpa_compat/fake_socket.h
 *
 * Replaces the vendored bk_patch/fake_socket.h (rw_task.c includes it
 * directly). Upstream that header exists because Armino's WPA port had no real
 * socket layer, so it ships its own `enum sock_type` and `struct sockaddr` --
 * both of which collide with the NuttX socket layer we do have
 * ("redefinition of 'struct sockaddr'").
 *
 * Kept here: the Armino-specific socket bookkeeping types, so vendored code
 * still compiles. Dropped: everything NuttX owns (sock_type, sockaddr, the
 * PF_*/ETH_P_* constants) -- those come from <sys/socket.h> and friends.
 *
 * Nothing in the compiled glue actually instantiates these types (checked over
 * rw_task.c / rwnx_rx.c / rwnx_tx.c / rw_msdu.c); they are declared for source
 * compatibility only.
 */

#ifndef __BK7258_WIFI_GLUE_WPA_COMPAT_FAKE_SOCKET_H
#define __BK7258_WIFI_GLUE_WPA_COMPAT_FAKE_SOCKET_H

#include <stdint.h>

#include <sys/socket.h>

#include "utils/list.h"
#include "os/os.h"

#ifdef __cplusplus
extern "C" {
#endif

typedef int SOCKET;

typedef struct
{
  struct dl_list data;
  unsigned char *msg;
  int            len;
  uint32_t       extra_info;
} SOCKET_MSG;

typedef struct
{
  struct dl_list sk_tx_msg;  /* Socket tx from non-rwip */
  struct dl_list sk_rx_msg;  /* Socket recv from rwip */
  struct dl_list sk_element; /* Link into the global socket list */
  SOCKET         sk;
} BK_SOCKET;

typedef struct
{
  struct dl_list  sk_head;
  beken_mutex_t   fs_mutex;
} SOCKET_ENTITY;

#ifndef SK_PRT
#  define SK_PRT(...)  do { } while (0)
#endif
#ifndef SK_WPRT
#  define SK_WPRT(...) do { } while (0)
#endif

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_WPA_COMPAT_FAKE_SOCKET_H */

