/*
 * chips/bk7258/wifi/glue/include/lwip/prot/ethernet.h
 *
 * Ethernet header layout and EtherType values for the vendored glue
 * (rwnx_rx.c:25 includes "prot/ethernet.h" and uses struct eth_hdr,
 * ETHTYPE_IP, ETHTYPE_ARP).
 *
 * Ours rather than vendored, for the same reason as lwip/pbuf.h: only the
 * on-the-wire layout is reused, not the lwIP stack. Upstream splits this
 * across prot/ethernet.h + prot/ieee.h and needs arch/cc.h for its
 * PACK_STRUCT_FLD_* macros; the layout itself is 14 fixed bytes.
 *
 * ETH_PAD_SIZE is 0 here (as in upstream opt.h:692), so SIZEOF_ETH_HDR is 14
 * and there is no leading padding field.
 */

#ifndef __BK7258_WIFI_GLUE_LWIP_PROT_ETHERNET_H
#define __BK7258_WIFI_GLUE_LWIP_PROT_ETHERNET_H

#include "lwip/arch.h"

#ifdef __cplusplus
extern "C" {
#endif

#define ETH_HWADDR_LEN   6
#define ETH_PAD_SIZE     0
#define SIZEOF_ETH_HDR   (14 + ETH_PAD_SIZE)

/** An Ethernet MAC address */

struct eth_addr
{
  u8_t addr[ETH_HWADDR_LEN];
} __attribute__((packed));

#define ETH_ADDR(b0, b1, b2, b3, b4, b5) {{b0, b1, b2, b3, b4, b5}}

/** Ethernet header. Field names match upstream: the glue dereferences
 * ->dest / ->src / ->type.
 */

struct eth_hdr
{
  struct eth_addr dest;
  struct eth_addr src;
  u16_t           type;
} __attribute__((packed));

/* EtherTypes, values as upstream lwip/prot/ieee.h (network byte order on the
 * wire; the glue compares against htons()-converted values).
 */

enum lwip_ieee_eth_type
{
  ETHTYPE_IP        = 0x0800u,
  ETHTYPE_ARP       = 0x0806u,
  ETHTYPE_WOL       = 0x0842u,
  ETHTYPE_RARP      = 0x8035u,
  ETHTYPE_VLAN      = 0x8100u,
  ETHTYPE_IPV6      = 0x86ddu,
  ETHTYPE_PPPOEDISC = 0x8863u,
  ETHTYPE_PPPOE     = 0x8864u,
  ETHTYPE_EAPOL     = 0x888eu,
  ETHTYPE_PROFINET  = 0x8892u,
  ETHTYPE_ETHERCAT  = 0x88a4u,
  ETHTYPE_LLDP      = 0x88ccu,
  ETHTYPE_SERCOS    = 0x88cdu,
  ETHTYPE_MRP       = 0x88e3u,
  ETHTYPE_PTP       = 0x88f7u,
  ETHTYPE_QINQ      = 0x9100u
};

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_LWIP_PROT_ETHERNET_H */

/*
 * chips/bk7258/wifi/glue/include/bk_misc.h
 *
 * Busy-delay helpers. bk_wifi_adapter.c:223 wraps delay() into g_wifi_funcs,
 * so libwifi.a calls it.
 *
 * Signatures are upstream's. Note that delay() is NOT a time unit: upstream
 * implements it as a bare nested busy loop (bk_system/delay.c:13, `for i<num:
