/* bk_err_t lives here, not in bk_err.h, to keep the header graph acyclic:
 * components/log.h has to include components/system.h (upstream log.h:22 does,
 * and vendored files such as wifi_v2.c rely on that to see MAC_TYPE_*), while
 * system.h needs bk_err_t for its return types. Sourcing the typedef from this
 * leaf header avoids system.h -> bk_err.h -> log.h -> system.h. bk_err.h
 * re-uses this typedef for its error macros.
 */

typedef int bk_err_t;

typedef __u16 __bitwise __le16;

/* bk_err_t itself comes from common/bk_typedef.h -- see the note there about
 * the header cycle that forces it.
 */

#include <common/bk_typedef.h>

#define ERR_TAG "err"

