/*
 * chips/bk7258/wifi/glue/flash_shim.c
 *
 * Flash / partition / eFuse accessors that the vendored bk_phy_adapter.c
 * registers into the PHY capability table, so libbk_phy.a reads RF calibration
 * through them.
 *
 * ==== Why these are stubs, and why they are shaped like this ====
 *
 * The RF calibration blob lives in a dedicated flash partition. Upstream's
 * genie project puts it at the tail of an 8 MiB flash (SYS_RF 0x007fe000,
 * 0x1000 bytes, per its generated partitions_gen.h). This team repo's own
 * partition table (board/bk7258-devkit/packaging/bundled/bk_ota_partitions.json)
 * declares only bootloader / app / app1 / download -- there is no RF partition
 * yet. Flash layout is a product decision, so this file does not invent one.
 *
 * The shape is forced by the caller:
 * bk_flash_partition_get_rf_firmware_info() (bk_phy_adapter.c:224-229) does
 *
 *     pt = bk_flash_partition_get_info(BK_PARTITION_SYS_RF);
 *     return pt->partition_start_addr;
 *
 * with no NULL check. So returning NULL is not "safe failure", it is a null
 * dereference during PHY init. Instead:
 *
 *   - get_info() returns a real, zero-length descriptor: no crash, and a
 *     length of 0 says "nothing here" to anything that bothers to look;
 *   - the actual gate is the read path. bk_flash_read_bytes(),
 *     bk_flash_partition_read() and bk_efuse_read_byte() all fail without
 *     touching the output buffer, so no garbage can be mistaken for
 *     calibration data.
 *
 * That ordering matters: silently returning zeros would let the PHY calibrate
 * against fabricated values, which is worse than a clean failure -- it can mean
 * out-of-spec RF output.
 *
 * Before RF bring-up (plan step 4) this file must be implemented for real:
 * add the RF partition to the team flash layout, then read it via the NuttX
 * MTD/progmem interface. Same milestone as the aon_pmu accessors in
 * hw_driver_shim.c.
 */

#include <nuttx/config.h>

#include <stdint.h>

#include <common/bk_err.h>

#include "driver/flash.h"
#include "driver/flash_partition.h"
#include "driver/efuse.h"
#include "temp_detect_pub.h"

/****************************************************************************
 * Private data
 ****************************************************************************/

/* Zero-length descriptor: non-NULL so the caller above does not fault, but
 * describing an empty region so nothing treats it as usable storage.
 */

static bk_logic_partition_t g_bk7258_rf_partition_unmapped =
{
  .partition_owner       = BK_FLASH_EMBEDDED,
  .partition_description = "unmapped (BK7258 RF partition not defined)",
  .partition_start_addr  = 0,
  .partition_length      = 0,
  .partition_options     = 0,
};

/****************************************************************************
 * Partition lookup
 ****************************************************************************/

bk_logic_partition_t *bk_flash_partition_get_info(bk_partition_t partition)
{
  (void)partition;
  return &g_bk7258_rf_partition_unmapped;
}

/****************************************************************************
 * Read paths -- the real gate. Each fails without writing the output buffer.
 ****************************************************************************/

bk_err_t bk_flash_read_bytes(uint32_t address, uint8_t *user_buf,
                             uint32_t size)
{
  (void)address;
  (void)user_buf;
  (void)size;
  return BK_FAIL;
}

bk_err_t bk_flash_partition_read(bk_partition_t partition, uint8_t *out_buffer,
                                 uint32_t offset, uint32_t buffer_len)
{
  (void)partition;
  (void)out_buffer;
  (void)offset;
  (void)buffer_len;
  return BK_FAIL;
}

bk_err_t bk_efuse_read_byte(uint8_t addr, uint8_t *data)
{
  /* eFuse holds trim/calibration bytes. Failing is the honest answer while the
   * BK7258 eFuse driver is unported; writing a fabricated value here would feed
   * the PHY silently wrong trim data.
   */

  (void)addr;
  (void)data;
  return BK_FAIL;
}

bk_err_t bk_efuse_write_byte(uint8_t addr, uint8_t data)
{
  /* Write refused outright: eFuse programming is irreversible. */

  (void)addr;
  (void)data;
  return BK_FAIL;
}

/****************************************************************************
 * Temperature detection
 ****************************************************************************/

int temp_detect_init(uint32_t init_val)
{
  /* Registered into the PHY capability table (bk_phy_adapter.c:543), and
   * CONFIG_TEMP_DETECT is 1 in the prebuilt baseline, so the runtime may start
   * temperature tracking for calibration compensation. Report failure rather
   * than pretending to have started: the BK7258 SARADC/temperature path is not
   * ported, so no compensation is actually happening.
   */

  (void)init_val;
  return -1;
}

