import re
def enum_vals(path, endname):
    txt=open(path,errors='ignore').read()
    m=re.search(r'typedef enum\s*\{(.*?)\}\s*'+endname, txt, re.S)
    if not m: return {}
    body=m.group(1); val=0; out={}
    for line in body.split('\n'):
        line=re.sub(r'/\*.*?\*/','',line); line=re.sub(r'//.*','',line).strip()
        if not line or line.startswith('#'): continue
        for part in line.split(','):
            part=part.strip()
            if not part: continue
            mm=re.match(r'^([A-Za-z_]\w*)\s*(?:=\s*(.+))?$', part)
            if not mm: continue
            name,expr=mm.group(1),mm.group(2)
            if expr:
                expr=expr.strip()
                try: val=int(expr,0)
                except ValueError: val=out.get(expr,val)
            out[name]=val; val+=1
    return out

