/*
 * chips/bk7258/wifi/glue/include/driver/int.h
 *
 * ICU interrupt driver surface the vendored pm.h includes.
 *
 * The ids and callback types live in driver/int_types.h, as upstream splits them
 * -- and that split matters here: this header used to declare
 * `typedef uint32_t icu_int_src_t`, which is incompatible with the enum the
 * value table needs (bk_wifi_adapter.c stores INT_SRC_* ids for libwifi.a).
 *
 * Registration itself stays unimplemented: Wi-Fi interrupt routing goes through
 * the team chip layer (enable bits in bk7258_memorymap.h driven by
 * sys_drv_int_enable/_group2_enable in glue/hw_driver_shim.c, IRQ numbers in
 * chips/bk7258/include/irq.h), not through Armino's ICU abstraction.
 */

#ifndef __BK7258_WIFI_GLUE_DRIVER_INT_H
#define __BK7258_WIFI_GLUE_DRIVER_INT_H

#include <stdint.h>

#include <common/bk_err.h>

