/****************************************************************************
 * Assertion output
 ****************************************************************************/

int shell_assert_out(bool bContinue, char *format, ...)
{
  va_list ap;
  int ret;

  /* Address stored in the vendor function table (bk_wifi_adapter.c:1400), so
   * libwifi.a prints through this while asserting.
   *
   * bContinue is upstream's "more output follows" hint for its async shell
   * (whether to hold the line open); NuttX stdio has no such notion, so it is
   * accepted and ignored rather than being given an invented meaning.
   *
   * Deliberately plain vprintf(): this runs on an assert path, where taking a
   * lock or routing through the work queue could deadlock the very fault it is
   * reporting.
   */

  (void)bContinue;

  va_start(ap, format);
  ret = vprintf(format, ap);
  va_end(ap);

  return ret;
}

