/*
 * chips/bk7258/wifi/glue/include/bk_rf_internal.h
 *
 * RF arbitration interface shared by the Wi-Fi and Bluetooth sides of the PHY.
 * Values reproduced from upstream components/bk_phy/include/bk_rf_internal.h.
 *
 * Two reasons every value matters:
 *   - CMD_RF_WIFIPLL_HOLD_BIT_SET/CLR and RF_WIFIPLL_HOLD_BY_WIFI_BIT go into
 *     the vendor value table (bk_wifi_adapter.c:1526-1528), so libwifi.a
 *     receives them verbatim;
 *   - rf_pll_ctrl() is called with these enums from
 *     bk_wifi_adapter.c:814/818, and it is *defined inside libbk_phy.a*
 *     (confirmed with nm: defined=1). So the enum ordinals are a real ABI
 *     contract with the prebuilt -- only the declaration belongs here, never an
 *     implementation, or the link would see a duplicate symbol.
 *
 * An earlier version of this header carried only the two PLL-hold bits and
 * mis-spelled RF_WIFIPLL_HOLD_BY_BLE_BIT as ..._BY_BT_BIT. Both are fixed here.
 */

#ifndef __BK7258_WIFI_GLUE_BK_RF_INTERNAL_H
#define __BK7258_WIFI_GLUE_BK_RF_INTERNAL_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Owner bits: who currently holds the RF, upstream :28-34. */

#define RF_BY_SARADC_BIT             (1 << 6)
#define RF_BY_TEMP_BIT               (1 << 5)
#define RF_BY_ATE_BT_BIT             (1 << 4)
#define RF_BY_ATE_WIFI_BIT           (1 << 3)
#define RF_BY_BKREG_BIT              (1 << 2)
#define RF_BY_BLE_BIT                (1 << 1)
#define RF_BY_WIFI_BIT               (1 << 0)

/* Wi-Fi PLL hold bits, upstream :39-40. */

#define RF_WIFIPLL_HOLD_BY_BLE_BIT   (1 << 1)
#define RF_WIFIPLL_HOLD_BY_WIFI_BIT  (1 << 0)

enum
{
  RF_CLOSE,
  RF_OPEN
};

enum
{
  CMD_RF_WIFIPLL_HOLD_BIT_SET,
  CMD_RF_WIFIPLL_HOLD_BIT_CLR
};

enum MODULE_TYPE_E
{
  MODULE_TYPE_BLE_BT,
  MODULE_TYPE_WIFI,
  MODULE_TYPE_THREAD,
  MODULE_TYPE_MAX
};

enum RF_OPERATION_E
{
  RF_OPERATION_INVALID,
  RF_OPERATION_FREE,
  RF_OPERATION_APPLY,
  RF_OPERATION_MAX
};

enum RF_PATH_E
{
  RF_PATH_WIFI_IQ,
  RF_PATH_BT_IQ,
  RF_PATH_BT_POLAR,
  RF_PATH_MAX
};

enum RF_PRIORITY_E
{
  RF_PRIORITY_BLE_BT_HIGH,
  RF_PRIORITY_WIFI_HIGH,
  RF_PRIORITY_BLE_BT_NORMAL,
  RF_PRIORITY_WIFI_NORMAL,
  RF_PRIORITY_MAX
};

enum RF_PLL_E
{
  RF_PLL_LOW,
  RF_PLL_HIGH,
  RF_PLL_MAX
};

enum RF_ARBIT_RESULT_E
{
  RF_ARBIT_RESULT_SUCCESS,
  RF_ARBIT_RESULT_CONFLICT,
  RF_ARBIT_RESULT_ERROR,
  RF_ARBIT_RESULT_MAX
};

struct RF_ARBITRATION_T
{
  enum MODULE_TYPE_E  module_type;
  enum RF_OPERATION_E operation;
  enum RF_PATH_E      rf_path;
  enum RF_PLL_E       rf_pll;
  enum RF_PRIORITY_E  priority;
  bool                is_save_when_failed;
  bool                is_need_switch_rf;
};

/* Implemented in libbk_phy.a -- declaration only. */

enum RF_ARBIT_RESULT_E rf_pll_ctrl(enum MODULE_TYPE_E module_type,
                                   enum RF_OPERATION_E operation,
                                   enum RF_PATH_E rf_path,
                                   enum RF_PLL_E rf_pll,
                                   enum RF_PRIORITY_E priority,
                                   bool is_save_when_failed);

#ifdef __cplusplus
}
#endif

#endif /* __BK7258_WIFI_GLUE_BK_RF_INTERNAL_H */

