/*
 * chips/bk7258/wifi/glue/bt_coex_shim.c
 *
 * Bluetooth-side coexistence hooks declared in glue/include/bluetooth_internal.h.
 * The vendored bk_phy_adapter.c registers wrappers around them into the PHY
 * function table, so libbk_phy.a can query BT transmit power and re-arm RF test
 * mode while sharing the PHY with Wi-Fi.
 *
 * These come from the Bluetooth stack, which this port does not include. Rather
 * than invent behaviour, each one reproduces exactly what upstream does when
 * CONFIG_BLUETOOTH is 0 (bk_phy_adapter.c:306-335): report power index 0 and do
 * nothing. So the runtime behaviour here is identical to a BT-less Armino build,
 * even though CONFIG_BLUETOOTH stays 1 to match the prebuilt baseline.
 *
 * Why 0 is a safe answer, unlike the RF calibration stubs: this is a *BT*
 * transmit-power index feeding coexistence arbitration. With no BT traffic there
 * is nothing to arbitrate, so "no BT power request" is true rather than merely
 * convenient. Once a Bluetooth stack is brought up on this chip, these must be
 * routed to it -- returning 0 then would understate BT power and could let Wi-Fi
 * and BT transmit over each other.
 */

#include <nuttx/config.h>

#include <stdint.h>

#include "bluetooth_internal.h"

/****************************************************************************
 * Public functions
 ****************************************************************************/

uint8_t get_tx_pwr_idx(void)
{
  /* Upstream's CONFIG_BLUETOOTH=0 branch returns 0 (bk_phy_adapter.c:312). */

  return 0;
}

void txpwr_max_set_bt_polar(void)
{
  /* No-op: upstream only calls this on BK7239N/BK7236/BK7286/BK7258 *with* BT
   * compiled in; without a BT stack there is no polar path to cap.
   */
}

void txpwr_max_set_bt_iq(void)
{
  /* No-op, same reasoning. Upstream additionally gates this on
   * CONFIG_BLUETOOTH_RF_MODE_POLAR.
   */
}

void bluetooth_rf_test_mode_retrig(void)
{
  /* No-op: RF test mode belongs to the BT controller's test harness. */
}

