/****************************************************************************
 * Name: bk7258_ip4addr_ntoa
 *
 * Description:
 *   Backs the inet_ntoa macro in glue/include/lwip/inet.h. See that header for
 *   why a macro is required: upstream's inet_ntoa applies `&(addr)` to its
 *   argument, so bk_wifi_adapter.c:152-155 ends up formatting the four bytes of
 *   the pointer parameter itself, not a pointed-to address.
 *
 *   Byte order follows upstream ip4addr_ntoa(), which indexes the stored u32
 *   through ip4_addr1..4 as `((const u8_t *)&addr->addr)[0..3]` -- i.e. the
 *   bytes are emitted in storage order, which for a network-byte-order address
 *   is already the dotted-quad order. No htonl/ntohl is involved, and adding one
 *   would reverse the octets.
 *
 *   Uses a static buffer, matching upstream's signature and its
 *   non-reentrancy. That is a property of the vendor API, not a shortcut: the
 *   caller returns the pointer straight through the function table, so it has
 *   nowhere to put a caller-supplied buffer. Only ever called from the vendor
 *   Wi-Fi task.
 *
 ****************************************************************************/

char *bk7258_ip4addr_ntoa(const void *addr)
{
  static char buf[16];  /* "255.255.255.255" + NUL */
  FAR const uint8_t *b = addr;

  if (addr == NULL)
    {
      buf[0] = '\0';
      return buf;
    }

  snprintf(buf, sizeof(buf), "%u.%u.%u.%u",
           (unsigned int)b[0], (unsigned int)b[1],
           (unsigned int)b[2], (unsigned int)b[3]);

  return buf;
}

#include <netinet/in.h>
#include <arpa/inet.h>

#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "components/netif.h"

/* For the bk7258_ip4addr_ntoa prototype, so the definition below is checked
 * against it. Safe here: this file calls inet_ntop, never inet_ntoa, so the
 * macro that header installs does not affect it.
 */

#include "lwip/inet.h"

